// Custom deleter for a C-style file handle using a lambda.
auto file_closer = [](FILE* fp) { if (fp) fclose(fp); };
std::unique_ptr<FILE, decltype(file_closer)> pFile(
    fopen("document.txt", "w"),
    file_closer
);

// Custom deleter for a third-party library resource.
struct ThirdPartyResource {};
ThirdPartyResource* createResource();
void releaseResource(ThirdPartyResource* res);

// Using a function pointer as a deleter for unique_ptr.
using ResourcePtr = std::unique_ptr<ThirdPartyResource, decltype(&releaseResource)>;
ResourcePtr pResource(createResource(), &releaseResource);

// Custom deleter with a shared_ptr. The deleter's type is not part of the shared_ptr's type.
std::shared_ptr<ThirdPartyResource> spResource(
    createResource(), 
    [](ThirdPartyResource* res) { releaseResource(res); }
);

// The resource is automatically released when the smart pointer is destroyed.
